154	export function apiErrorToStatus(code: string): number {
155	  switch (code) {
156	    case 'NOT_FOUND':
157	      return 404;
158	    case 'FORBIDDEN':
159	      return 403;
160	    case 'VALIDATION_ERROR':
161	      return 400;
162	    case 'CONFLICT':
163	      return 409;
164	    default:
165	      return 500;
166	  }
167	}
