169	// ---------------------------------------------------------------------------
170	// Body reading
171	// ---------------------------------------------------------------------------
172	
173	/** Maximum accepted request body size (1 MiB). */
174	export const MAX_BODY_BYTES = 1_048_576;
175	
176	/** Thrown by {@link readBody} when the request body exceeds {@link MAX_BODY_BYTES}. */
177	export class PayloadTooLargeError extends Error {
178	  constructor() {
179	    super('Payload Too Large');
180	    this.name = 'PayloadTooLargeError';
181	  }
182	}
183	
184	/**
185	 * Reads the full request body as a UTF-8 string, enforcing a size limit of
186	 * {@link MAX_BODY_BYTES} (1 MiB).
187	 *
188	 * @throws {PayloadTooLargeError} When the body exceeds the limit (detected
189	 *   either via Content-Length header pre-check or streaming byte count).
190	 *   **Callers must catch this error and return a 413 response.**
191	 *
192	 * @param req - The incoming HTTP request.
193	 * @returns The full body string.
194	 */
195	function readBody(req: IncomingMessage): Promise<string> {
196	  return new Promise((resolve, reject) => {
197	    // Content-Length pre-check: reject immediately if the declared size exceeds the limit.
198	    const declaredLength = req.headers['content-length'];
199	    if (declaredLength !== undefined) {
200	      const n = parseInt(declaredLength, 10);

201	      if (!isNaN(n) && n > MAX_BODY_BYTES) {
202	        req.resume();  // drain body data from socket buffer
203	        reject(new PayloadTooLargeError());
204	        return;
205	      }
206	    }
207	
208	    const chunks: Buffer[] = [];
209	    let totalBytes = 0;
210	    let rejected = false;
211	
212	    req.on('data', (chunk: Buffer) => {
213	      if (rejected) return;
214	      totalBytes += chunk.length;
215	      if (totalBytes > MAX_BODY_BYTES) {
216	        rejected = true;
217	        reject(new PayloadTooLargeError());
218	        // Drain remaining data so the 413 response can be sent cleanly.
219	        req.resume();
220	        return;
221	      }
222	      chunks.push(chunk);
223	    });
224	    req.on('end', () => {
225	      if (!rejected) resolve(Buffer.concat(chunks).toString('utf-8'));
226	    });
227	    req.on('error', (err) => {
228	      if (!rejected) reject(err);
229	    });
230	  });
231	}
232	
233	/**
234	 * Reads and parses the request body as JSON, enforcing the same size limit as
235	 * {@link readBody}. Throws {@link PayloadTooLargeError} for oversized bodies
236	 * and {@link ApiError} with code `VALIDATION_ERROR` for invalid JSON.
237	 *
238	 * @param req - The incoming HTTP request.
239	 * @returns The parsed JSON value.
240	 */
241	async function readJsonBody(req: IncomingMessage): Promise<unknown> {
242	  const raw = await readBody(req);
243	  try {
244	    return JSON.parse(raw);
245	  } catch {
246	    throw new ApiError('VALIDATION_ERROR', 'Invalid JSON body.');
247	  }
248	}
