256	// ---------------------------------------------------------------------------
257	// Meta helpers
258	// ---------------------------------------------------------------------------
259	
260	/**
261	 * Guards against path-traversal attacks on URL parameters that are used as
262	 * filesystem path segments.
263	 *
264	 * Rejects any segment that is empty or does not match {@link SAFE_SLUG_REGEX}
265	 * (`/^[a-z0-9][a-z0-9-]*$/`). Throws {@link ApiError} `NOT_FOUND` so that
266	 * callers receive the same status as a missing project — no information leak.
267	 *
268	 * @param segment - The raw URL parameter value to validate.
269	 */
270	function assertSafeSlug(segment: string): void {
271	  if (!segment || !SAFE_SLUG_REGEX.test(segment)) {
272	    throw new ApiError('NOT_FOUND', 'Invalid repo or slug parameter.');
273	  }
274	}
275	
276	/**
277	 * Reads the `.meta.json` for a namespaced project at
278	 * `{ledgerRoot}/{repoUrlParam}/{slugUrlParam}/.meta.json`.
279	 *
280	 * Returns the stored `repository_name` value, falling back to `repoUrlParam`
281	 * when the field is absent or null.
282	 *
283	 * When the meta file exists but contains malformed JSON, the function still
284	 * falls back to `repoUrlParam` — but writes a warning to `process.stderr`
285	 * (format: `[server] Warning: malformed .meta.json at {path} — falling back
286	 * to URL param '…'`) so operators can detect corrupt meta files during
287	 * troubleshooting. API callers always receive the fallback value in this case.
288	 *
289	 * Throws {@link ApiError} `NOT_FOUND` when the meta file does not exist —
290	 * indicating that the `{repo}/{slug}` combination is not a known project in
291	 * this ledger. This is the project-existence check for namespaced routes.
292	 * Using `NOT_FOUND` (rather than a 400 or `VALIDATION_ERROR`) is intentional
293	 * information-hiding: invalid-input and missing-project cases are
294	 * indistinguishable from the client side.
295	 *
296	 * Both `repoUrlParam` and `slugUrlParam` are validated via {@link assertSafeSlug}
297	 * before any filesystem access is attempted (defence-in-depth).
298	 */
299	export async function resolveRepoName(
300	  ledgerRoot: string,
301	  repoUrlParam: string,
302	  slugUrlParam: string,
303	): Promise<string> {
304	  assertSafeSlug(repoUrlParam);
305	  assertSafeSlug(slugUrlParam);
306	  const metaPath = join(ledgerRoot, repoUrlParam, slugUrlParam, '.meta.json');
307	  let raw: string;
308	  try {
309	    raw = await readFile(metaPath, 'utf-8');
310	  } catch {
311	    throw new ApiError('NOT_FOUND', `Project not found: ${slugUrlParam}`);
312	  }
313	  try {
314	    const meta = JSON.parse(raw) as { repository_name?: string | null };
315	    return meta.repository_name ?? repoUrlParam;
316	  } catch {
317	    // Malformed .meta.json — project directory exists, fall back to URL param.
318	    // Log to stderr so operators can detect corrupt meta files during troubleshooting.
319	    process.stderr.write(`[server] Warning: malformed .meta.json at ${metaPath} — falling back to URL param '${repoUrlParam}'\n`);
320	    return repoUrlParam;

321	  }
322	}
