1190	async function serveStatic(
1191	  req: IncomingMessage,
1192	  res: ServerResponse,
1193	  port: number
1194	): Promise<void> {
1195	  const urlPath = (req.url ?? '/').split('?')[0]!;
1196	  const filePath =
1197	    urlPath === '/' ? join(PUBLIC_DIR, 'index.html') : join(PUBLIC_DIR, urlPath.slice(1));
1198	
1199	  // Security: prevent path traversal outside PUBLIC_DIR
1200	  const resolved = resolve(filePath);
1201	  if (!resolved.startsWith(PUBLIC_DIR)) {
1202	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1203	    return;
1204	  }
1205	
1206	  const ext = extname(filePath);
1207	  const mimeType = MIME_TYPES[ext] ?? 'application/octet-stream';
1208	
1209	  try {
1210	    const content = await readFile(filePath);
1211	    res.writeHead(200, {
1212	      'Content-Type': mimeType,
1213	      'Content-Length': content.length,
1214	      'Cache-Control': 'no-store',
1215	      ...corsHeaders(port),
1216	      ...securityHeaders(),
1217	    });
1218	    res.end(content);
1219	  } catch {
1220	    sendError(res, 404, 'NOT_FOUND', 'Not found.', port);
1221	  }
1222	}
